class CircularLinkedList:
    def __init__(self):
        self.head = None   # empty list

    def display(self):
        if self.head is None:
            print("Empty")
            return
        curr = self.head
        print(curr.data, end=" -> ")
        curr = curr.next
        while curr != self.head:   # stop when we come back to head
            print(curr.data, end=" -> ")
            curr = curr.next
        print("(back to head)")

class Node:
